// The spine's own ack-fall hold (bd_link.v DACK), sized by rule H like any
// other -- its data is constant, but the audit cannot know that.
`ifndef BD_SZ_UPIPE_UACK
 `define BD_SZ_UPIPE_UACK 6
`endif
// ... and its stage-to-stage request pad (bd_link.v SDELAY), sized by rule I.
`ifndef BD_SZ_UPIPE_SDELAY
 `define BD_SZ_UPIPE_SDELAY 3
`endif

`default_nettype none
module bdc_xorshift_top (input wire pin_in, output wire pin_out);

    wire rst = pin_in;

    // A free-running spine: the pipe acknowledges itself, so nothing settles
    // and its 69 latch bits keep changing.  Its latches are keep'd LUT
    // feedback loops and so are opaque to constant folding, which is the only
    // reason the datapath below survives synthesis.
    wire        p_ack_in, p_req_out;
    wire [68:0] spine_q;
    wire        spine;
    bd_delay #(.N(3)) uspin (.a(p_ack_in), .z(spine));

    bd_pipe #(.W(69), .N(4), .SDELAY(`BD_SZ_UPIPE_SDELAY),
              .DACK(`BD_SZ_UPIPE_UACK)) upipe (
        .rst(rst),
        .req_in(~spine), .ack_in(p_ack_in),
        .data_in({68'hc5a3c5a3c5a3c5a3c, pin_in}),
        .req_out(p_req_out), .ack_out(p_req_out), .data_out(spine_q));

    wire seed_ack;
    wire rounds_ack;
    wire start_ack;
    wire out0_req;
    wire [31:0] out0_data;
    wire p_end_req;

    bdc_xorshift #(
        .DELAY_UCMPI0(`BD_SZ_UUT_UCMPI0),
        .DELAY_UMUX0(`BD_SZ_UUT_UMUX0),
        .DELAY_UMUX1(`BD_SZ_UUT_UMUX1),
        .DELAY_UMUX2(`BD_SZ_UUT_UMUX2),
        .DELAY_UCONTROL_MERGE0(`BD_SZ_UUT_UCONTROL_MERGE0),
        .DELAY_UXORI1(`BD_SZ_UUT_UXORI1),
        .DELAY_UXORI2(`BD_SZ_UUT_UXORI2),
        .DELAY_UADDI0(`BD_SZ_UUT_UADDI0),
        .DELAY_UCMPI1(`BD_SZ_UUT_UCMPI1),
        .DELAY_UMUX3(`BD_SZ_UUT_UMUX3),
        .DELAY_UCONTROL_MERGE1(`BD_SZ_UUT_UCONTROL_MERGE1),
        .DELAY_ULINK_N1__1(`BD_SZ_UUT_ULINK_N1__1),
        .DELAY_ULINK_N1__1_UACK(`BD_SZ_UUT_ULINK_N1__1_UACK),
        .DELAY_ULINK_N11__1(`BD_SZ_UUT_ULINK_N11__1),
        .DELAY_ULINK_N11__1_UACK(`BD_SZ_UUT_ULINK_N11__1_UACK),
        .DELAY_ULINK_N12__0(`BD_SZ_UUT_ULINK_N12__0),
        .DELAY_ULINK_N12__0_UACK(`BD_SZ_UUT_ULINK_N12__0_UACK),
        .DELAY_ULINK_N12__1(`BD_SZ_UUT_ULINK_N12__1),
        .DELAY_ULINK_N12__1_UACK(`BD_SZ_UUT_ULINK_N12__1_UACK),
        .DELAY_ULINK_N12__1_SDELAY(`BD_SZ_UUT_ULINK_N12__1_SDELAY),
        .DELAY_ULINK_N12__2(`BD_SZ_UUT_ULINK_N12__2),
        .DELAY_ULINK_N12__2_UACK(`BD_SZ_UUT_ULINK_N12__2_UACK),
        .DELAY_ULINK_N25(`BD_SZ_UUT_ULINK_N25),
        .DELAY_ULINK_N25_UACK(`BD_SZ_UUT_ULINK_N25_UACK),
        .DELAY_ULINK_N30__1(`BD_SZ_UUT_ULINK_N30__1),
        .DELAY_ULINK_N30__1_UACK(`BD_SZ_UUT_ULINK_N30__1_UACK),
        .DELAY_ULINK_N6(`BD_SZ_UUT_ULINK_N6),
        .DELAY_ULINK_N6_UACK(`BD_SZ_UUT_ULINK_N6_UACK),
        .DELAY_ULINK_N6_SDELAY(`BD_SZ_UUT_ULINK_N6_SDELAY),
        .DELAY_ULINK_N7(`BD_SZ_UUT_ULINK_N7),
        .DELAY_ULINK_N7_UACK(`BD_SZ_UUT_ULINK_N7_UACK),
        .DELAY_ULINK_N8(`BD_SZ_UUT_ULINK_N8),
        .DELAY_ULINK_N8_UACK(`BD_SZ_UUT_ULINK_N8_UACK),
        .DELAY_ULINK_N_FALSERESULT_1(`BD_SZ_UUT_ULINK_N_FALSERESULT_1),
        .DELAY_ULINK_N_FALSERESULT_1_UACK(`BD_SZ_UUT_ULINK_N_FALSERESULT_1_UACK),
        .DELAY_ULINK_N_FALSERESULT_1_SDELAY(`BD_SZ_UUT_ULINK_N_FALSERESULT_1_SDELAY),
        .DELAY_ULINK_N_FALSERESULT_9(`BD_SZ_UUT_ULINK_N_FALSERESULT_9),
        .DELAY_ULINK_N_FALSERESULT_9_UACK(`BD_SZ_UUT_ULINK_N_FALSERESULT_9_UACK),
        .DELAY_ULINK_N_FALSERESULT_9_SDELAY(`BD_SZ_UUT_ULINK_N_FALSERESULT_9_SDELAY),
        .DELAY_ULINK_N_INDEX_15(`BD_SZ_UUT_ULINK_N_INDEX_15),
        .DELAY_ULINK_N_INDEX_15_UACK(`BD_SZ_UUT_ULINK_N_INDEX_15_UACK),
        .DELAY_ULINK_N_INDEX_15_SDELAY(`BD_SZ_UUT_ULINK_N_INDEX_15_SDELAY),
        .DELAY_ULINK_N_TRUERESULT_0(`BD_SZ_UUT_ULINK_N_TRUERESULT_0),
        .DELAY_ULINK_N_TRUERESULT_0_UACK(`BD_SZ_UUT_ULINK_N_TRUERESULT_0_UACK),
        .DELAY_ULINK_N_TRUERESULT_0_SDELAY(`BD_SZ_UUT_ULINK_N_TRUERESULT_0_SDELAY),
        .DELAY_ULINK_N_TRUERESULT_10(`BD_SZ_UUT_ULINK_N_TRUERESULT_10),
        .DELAY_ULINK_N_TRUERESULT_10_UACK(`BD_SZ_UUT_ULINK_N_TRUERESULT_10_UACK),
        .DELAY_ULINK_N_TRUERESULT_10_SDELAY(`BD_SZ_UUT_ULINK_N_TRUERESULT_10_SDELAY),
        .DELAY_ULINK_N_TRUERESULT_12(`BD_SZ_UUT_ULINK_N_TRUERESULT_12),
        .DELAY_ULINK_N_TRUERESULT_12_UACK(`BD_SZ_UUT_ULINK_N_TRUERESULT_12_UACK),
        .DELAY_ULINK_N_TRUERESULT_12_SDELAY(`BD_SZ_UUT_ULINK_N_TRUERESULT_12_SDELAY),
        .DELAY_ULINK_N_TRUERESULT_2(`BD_SZ_UUT_ULINK_N_TRUERESULT_2),
        .DELAY_ULINK_N_TRUERESULT_2_UACK(`BD_SZ_UUT_ULINK_N_TRUERESULT_2_UACK),
        .DELAY_ULINK_N_TRUERESULT_2_SDELAY(`BD_SZ_UUT_ULINK_N_TRUERESULT_2_SDELAY),
        .DELAY_ULINK_N_TRUERESULT_6(`BD_SZ_UUT_ULINK_N_TRUERESULT_6),
        .DELAY_ULINK_N_TRUERESULT_6_UACK(`BD_SZ_UUT_ULINK_N_TRUERESULT_6_UACK),
        .DELAY_ULINK_N_TRUERESULT_6_SDELAY(`BD_SZ_UUT_ULINK_N_TRUERESULT_6_SDELAY),
        .DELAY_ULINK_N_TRUERESULT_8(`BD_SZ_UUT_ULINK_N_TRUERESULT_8),
        .DELAY_ULINK_N_TRUERESULT_8_UACK(`BD_SZ_UUT_ULINK_N_TRUERESULT_8_UACK)) uut (
        .rst(rst),
        .seed_req(spine_q[0]),
        .seed_data(spine_q[34:3]),
        .seed_ack(seed_ack),
        .rounds_req(spine_q[1]),
        .rounds_data(spine_q[66:35]),
        .rounds_ack(rounds_ack),
        .start_req(spine_q[2]),
        .start_ack(start_ack),
        .out0_req(out0_req), .out0_ack(spine_q[67]),
        .out0_data(out0_data),
        .p_end_req(p_end_req), .p_end_ack(spine_q[68]));

    // EVERY output is observed, requests included.  An output nobody reads is
    // an output yosys deletes, and a deleted request takes its whole matched
    // delay with it -- after which tighten.py measures a cell with no delay in
    // it and calls that a violation.
    assign pin_out = p_req_out ^ seed_ack ^ rounds_ack ^ start_ack ^ out0_req ^ ^out0_data ^ p_end_req;
endmodule
`default_nettype wire
